const body = $input.first().json;
const email = (body.email || '').trim().toLowerCase();
const phone = (body.phone || '').replace(/[^0-9+]/g, '');
if (!email && !phone) {
  throw new Error('INVALID_PAYLOAD: Missing both email and phone');
}
const idempotencyKey = `${email}::${phone}::${body.utm_campaign || 'direct'}`;
return [{ json: { ...body, normalized_email: email, normalized_phone: phone, idempotency_key: idempotencyKey, ingested_at: new Date().toISOString() } }];
